+    // Whether the current time is within the do not disturb schedule, to enable it only when the schedule starts
+    // so that turning it off manually lasts until the next time
+    property bool inSchedule: false
+
+    function checkSchedule() {
+        const now = new Date();
+        let end = null;
+
+        if (notificationSettings.inhibitNotificationsOnSchedule) {
+            const start = notificationSettings.inhibitionScheduleStart;
+            const startMinutes = start.getHours() * 60 + start.getMinutes();
+            const endTime = notificationSettings.inhibitionScheduleEnd;
+            const endMinutes = endTime.getHours() * 60 + endTime.getMinutes();
+            const nowMinutes = now.getHours() * 60 + now.getMinutes();
+
+            const inside = startMinutes < endMinutes
+                ? (nowMinutes >= startMinutes && nowMinutes < endMinutes)
+                : (nowMinutes >= startMinutes || nowMinutes < endMinutes);
+
+            if (startMinutes !== endMinutes && inside) {
+                end = new Date(now);
+                end.setHours(endTime.getHours(), endTime.getMinutes(), 0, 0);
+                if (end <= now) {
+                    end.setDate(end.getDate() + 1);
+                }
+            }
+        }
+
+        if (end && !globals.inSchedule) {
+            const inhibitedUntil = notificationSettings.notificationsInhibitedUntil;
+            if (isNaN(inhibitedUntil.getTime()) || inhibitedUntil < end) {
+                notificationSettings.notificationsInhibitedUntil = end;
+                notificationSettings.save();
+            }
+        }
+
+        globals.inSchedule = end !== null;
+    }
+
     function revokeInhibitions() {
         notificationSettings.notificationsInhibitedUntil = undefined;
         notificationSettings.revokeApplicationInhibitions();
@@ -464,6 +506,7 @@ QtObject {

     property NotificationManager.Settings notificationSettings: NotificationManager.Settings {
         onNotificationsInhibitedUntilChanged: globals.checkInhibition()
+        onSettingsChanged: globals.checkSchedule()
     }

     property TaskManager.TasksModel tasksModel: TaskManager.TasksModel {
@@ -474,6 +517,7 @@ QtObject {
     // This periodically checks whether do not disturb mode timed out and updates the "minutes ago" labels
     property Clock clockSource: Clock {
         onDateTimeChanged: {
+            globals.checkSchedule();
             globals.checkInhibition();
             globals.timeChanged();
         }
diff --git a/kcms/notifications/ui/TimeField.qml b/kcms/notifications/ui/TimeField.qml
new file mode 100644
index 0000000000..c10c2fef60
--- /dev/null
+++ b/kcms/notifications/ui/TimeField.qml
@@ -0,0 +1,101 @@
+/*
+    SPDX-FileCopyrightText: 2025 Vlad Zahorodnii <vlad.zahorodnii@kde.org>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+import QtQuick
+import QtQuick.Controls as QQC2
+import QtQuick.Layouts
+
+RowLayout {
+    id: root
+
+    readonly property var locale: Qt.locale()
+    readonly property bool isAmPm: locale.timeFormat().toUpperCase().includes("AP")
+    property date value: new Date()
+
+    signal activated(value: date)
+
+    onValueChanged: refresh();
+
+    QQC2.SpinBox {
+        id: hoursSpinBox
+        from: isAmPm ? 1 : 0
+        to: isAmPm ? 12 : 23
+        wrap: true
+        onValueModified: notify();
+    }
+
+    QQC2.Label {
+        text: i18nc("Time separator between hours and minutes", ":")
+        textFormat: Text.PlainText
+    }
+
+    QQC2.SpinBox {
+        id: minutesSpinBox
+        from: 0
+        to: 59
+        wrap: true
+        onValueModified: notify();
+    }
+
+    QQC2.SpinBox {
+        id: amPmSpinBox
+
+        readonly property list<string> items: [root.locale.amText, root.locale.pmText]
+
+        visible: isAmPm
+        from: 0
+        to: items.length - 1
+        wrap: true
+        validator: RegularExpressionValidator {
+            regularExpression: new RegExp("(" + amPmSpinBox.items.map(meridiem => meridiem.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|") + ")", "i")
+        }
+        textFromValue: function(value, locale) {
+            return items[value];
+        }
+        valueFromText: function(text, locale) {
+            const upperText = text.toUpperCase();
+            for (const [index, value] of items.entries()) {
+                if (value.toUpperCase() === upperText) {
+                    return index;
+                }
+            }
+            return value;
+        }
+        onValueModified: notify();
+    }
+
+    function notify(): void {
+        let hours = hoursSpinBox.value;
+        if (isAmPm) {
+            if (hours === 12) {
+                hours = 0;
+            }
+            if (amPmSpinBox.value === 1) { // pm
+                hours += 12;
+            }
+        }
+
+        const date = new Date();
+        date.setHours(hours, minutesSpinBox.value, 0, 0);
+        activated(date);
+    }
+
+    function refresh(): void {
+        let hours = value.getHours();
+        if (isAmPm) {
+            hours %= 12;
+            if (hours === 0) {
+                hours = 12;
+            }
+        }
+
+        hoursSpinBox.value = hours;
+        minutesSpinBox.value = value.getMinutes();
+        amPmSpinBox.value = value.getHours() >= 12;
+    }
+
+    Component.onCompleted: refresh();
+}
