+bool Settings::inhibitNotificationsOnSchedule() const
+{
+    return d->dndSettings.onSchedule();
+}
+
+void Settings::setInhibitNotificationsOnSchedule(bool inhibit)
+{
+    if (inhibit == inhibitNotificationsOnSchedule()) {
+        return;
+    }
+
+    d->dndSettings.setOnSchedule(inhibit);
+    d->setDirty(true);
+}
+
+QTime Settings::inhibitionScheduleStart() const
+{
+    return d->dndSettings.scheduleStart();
+}
+
+void Settings::setInhibitionScheduleStart(const QTime &time)
+{
+    if (time == inhibitionScheduleStart()) {
+        return;
+    }
+
+    d->dndSettings.setScheduleStart(time);
+    d->setDirty(true);
+}
+
+QTime Settings::inhibitionScheduleEnd() const
+{
+    return d->dndSettings.scheduleEnd();
+}
+
+void Settings::setInhibitionScheduleEnd(const QTime &time)
+{
+    if (time == inhibitionScheduleEnd()) {
+        return;
+    }
+
+    d->dndSettings.setScheduleEnd(time);
+    d->setDirty(true);
+}
